const BaseF3FilingSchema = z
  .object({
    amended_address: z.string().nullable().exactOptional(),
    amended_by: z.int32().exactOptional(),
    amendment: z.string().nullable().exactOptional(),
    amendment_chain: z.array(z.int32()).exactOptional(),
    beginning_image_number: z.string().exactOptional(),
    candidate_first_name: z.string().nullable().exactOptional(),
    candidate_id: z.string().nullable().exactOptional(),
    candidate_last_name: z.string().nullable().exactOptional(),
    candidate_middle_name: z.string().nullable().exactOptional(),
    candidate_name: z.string().exactOptional(),
    candidate_prefix: z.string().nullable().exactOptional(),
    candidate_suffix: z.string().nullable().exactOptional(),
    cash_on_hand_beginning_period: z.int32().nullable().exactOptional(),
    city: z.string().nullable().exactOptional(),
    committee_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "\nA unique identifier assigned to each committee or filer registered with the FEC. In general committee id's begin with the letter C which is followed by eight digits.\n",
      }),
    committee_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The name of the committee. If a committee changes its name,     the most recent name will be shown. Committee names are not unique. Use committee_id     for looking up records.',
      }),
    coverage_end_date: z.iso.date().nullable().exactOptional(),
    coverage_start_date: z.iso.date().nullable().exactOptional(),
    csv_url: z.string().exactOptional(),
    district: z.int32().nullable().exactOptional(),
    document_description: z.string().exactOptional(),
    election_date: z.iso.date().nullable().exactOptional(),
    election_state: z.string().nullable().exactOptional(),
    f3z1: z.int32().nullable().exactOptional(),
    fec_file_id: z.string().exactOptional(),
    fec_url: z.string().exactOptional(),
    file_number: z.int32().exactOptional(),
    general_election: z.string().nullable().exactOptional(),
    is_amended: z.boolean().exactOptional(),
    most_recent: z.boolean().exactOptional(),
    most_recent_filing: z.int32().exactOptional(),
    pdf_url: z.string().exactOptional(),
    prefix: z.string().nullable().exactOptional(),
    primary_election: z.string().nullable().exactOptional(),
    receipt_date: z.iso.date().nullable().exactOptional(),
    report: z.string().nullable().exactOptional(),
    report_type: z.string().nullable().exactOptional(),
    report_year: z.int32().exactOptional(),
    rpt_pgi: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Election type \nConvention, Primary,\nGeneral, Special,\nRunoff etc.\n',
      }),
    runoff_election: z.string().nullable().exactOptional(),
    sign_date: z.iso.date().nullable().exactOptional(),
    special_election: z.string().nullable().exactOptional(),
    state: z.string().nullable().exactOptional(),
    street_1: z.string().nullable().exactOptional(),
    street_2: z.string().nullable().exactOptional(),
    suffix: z.string().nullable().exactOptional(),
    summary_lines: z.string().exactOptional(),
    treasurer_first_name: z.string().nullable().exactOptional(),
    treasurer_last_name: z.string().nullable().exactOptional(),
    treasurer_middle_name: z.string().nullable().exactOptional(),
    treasurer_name: z.string().exactOptional(),
    zip: z.string().nullable().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('BaseF3Filing')

const BaseF3FilingPageSchema = z
  .object({
    pagination: OffsetInfoSchema.exactOptional(),
    results: z.array(BaseF3FilingSchema).exactOptional(),
  })
  .openapi({ required: [] })
