const CalendarDateSchema = z
  .object({
    all_day: z.boolean().nullable().exactOptional(),
    calendar_category_id: z
      .int32()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '\nEach type of event has a calendar category with an integer id. Options are: Open Meetings: 32, Executive Sessions: 39, Public Hearings: 40,\nConferences: 33, Roundtables: 34, Election Dates: 36, Federal Holidays: 37, FEA Periods: 38, Commission Meetings: 20,\nReporting Deadlines: 21, Conferences and Outreach: 22, AOs and Rules: 23, Other: 24, Quarterly: 25, Monthly: 26,\nPre and Post-Elections: 27, EC Periods:28, and IE Periods: 29\n',
      }),
    category: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '\nEach type of event has a calendar category with an integer id. Options are: Open Meetings: 32, Executive Sessions: 39, Public Hearings: 40,\nConferences: 33, Roundtables: 34, Election Dates: 36, Federal Holidays: 37, FEA Periods: 38, Commission Meetings: 20,\nReporting Deadlines: 21, Conferences and Outreach: 22, AOs and Rules: 23, Other: 24, Quarterly: 25, Monthly: 26,\nPre and Post-Elections: 27, EC Periods:28, and IE Periods: 29\n',
      }),
    description: z.string().exactOptional(),
    end_date: z.string().exactOptional(),
    event_id: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'An unique ID for an event. Useful for downloading a single event to your calendar. This ID is not a permanent, persistent ID.',
      }),
    location: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: '\nCan be state address or room.\n' }),
    start_date: z.string().exactOptional(),
    state: z
      .array(z.string())
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The state field only applies to election dates and reporting deadlines, reporting periods and all other dates do not have the array of states to filter on',
      }),
    summary: z.string().exactOptional(),
    url: z.string().nullable().exactOptional().openapi({ description: '\nA url for that event\n' }),
  })
  .openapi({ required: [] })
  .openapi('CalendarDate')

